import{_ as e,o as r,c as o,a5 as t}from"./chunks/framework.CXvGqWf0.js";const m=JSON.parse('{"title":"漫画 · 第 52 话 主线程与长任务治理","description":"","frontmatter":{},"headers":[],"relativePath":"comics/perf/EP.52-main-thread-long-tasks.md","filePath":"comics/perf/EP.52-main-thread-long-tasks.md","lastUpdated":1793421609000}'),l={name:"comics/perf/EP.52-main-thread-long-tasks.md"};function s(i,a,n,d,h,c){return r(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="漫画-·-第-52-话-主线程与长任务治理" tabindex="-1">漫画 · 第 52 话 主线程与长任务治理 <a class="header-anchor" href="#漫画-·-第-52-话-主线程与长任务治理" aria-label="Permalink to &quot;漫画 · 第 52 话 主线程与长任务治理&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/perf/04-main-thread-long-tasks">docs/perf/04-main-thread-long-tasks.md</a> ｜ 原画：<a href="./EP.52-main-thread-long-tasks.svg">EP.52-main-thread-long-tasks.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话主角。兴冲冲加了&quot;一键导出 80 万行&quot;，点下去页面直接白屏，输入框打字半天不回显。</li><li><strong>标签君</strong>：结构师，把事件循环画成三条泳道，解释什么叫长任务、切片和 Worker。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>导出按钮写了一个同步 <code>for</code> 循环，80 万行一次跑完，主线程被锁 1.2 秒。用户看到白屏、输入无响应，甚至以为页面崩了。像素酱以为&quot;数据太大没办法&quot;，标签君说：数据没变，变的是任务——把它切成可中断的小块，或者干脆搬去 Worker，主线程就能继续响应。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>一次点击触发一个 1.2s 的同步任务：进度条停在 0%，输入框的字符要等任务结束才出现。主线程同一时间只能做一件事，渲染、事件处理、脚本执行都排在它后面。用户感知到的不是&quot;导出慢&quot;，而是&quot;整个页面死了&quot;——白屏只是表象，长任务才是根因。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>浏览器把超过 50ms 的任务标记为长任务。三条退路：① 切片，把大循环按 20ms 左右一段拆开，每片结束调用 <code>await scheduler.yield()</code> 或 <code>setTimeout(0)</code> 让出主线程，让输入和绘制的回调插进来；② 协作式让出，让进度条每片都更新一次；③ 计算搬进 Web Worker，纯数据转换不碰 DOM，主线程只负责收发消息与渲染。图上三条泳道对比：一整块红条、一排小绿块、以及 Worker 与主线程并行。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>导出面板的进度条从 0 平滑走到 100%，12 个切片、8.6 秒完成，期间可取消、可滚动；INP 从 620ms 降到 90ms，输入回显从 1.2s 降到 0.1s。注意总耗时并没有魔法般变短，改变的是&quot;等待的形态&quot;：用户始终能操作，进度始终在动，长任务被拆成了不会阻塞交互的小块。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>超过 50ms 就是长任务：输入、点击、滚动都只能排队等它结束。</li><li>切片的关键是可中断：每片留 <code>yield</code>，让浏览器有机会处理交互与绘制。</li><li>纯计算进 Worker：DOM 只留在主线程，别在 Worker 里碰页面。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：把同步循环改成 <code>setTimeout(fn, 0)</code> 递归切片后，总耗时反而变长了，这样优化值得吗？</p><p><strong>答</strong>：值得，但要分清指标。切片会增加调度开销，总墙钟时间可能上升；收益在 INP、输入回显和进度反馈——用户不再觉得页面卡死。判断标准应是交互延迟与可取消性，而非单纯总时长。如果计算量大且无需 DOM，优先搬进 Worker，主线程几乎零占用；切片适合必须操作 DOM 或需要频繁汇报进度的场景。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>同步导出 vs 切片导出 vs Worker 导出三组对照：<a href="./../../examples/perf/04-main-thread-long-tasks">examples/perf/04-main-thread-long-tasks</a></li><li>用 Performance 面板录制，观察长任务红色角标与输入事件的排队关系。</li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>任务不堵了，但首包还是 6MB、发版还会白屏。第 53 话《资源与缓存策略》——缓存决策树、Service Worker 三策略，以及内容寻址为什么能救命。</p>',22)])])}const p=e(l,[["render",s]]);export{m as __pageData,p as default};
